def has_1pos_and_kwonly(func):
    """Check if function has exactly 1 positional arg and possibly keyword-only args."""
    if PY2:
        return False
    spec = inspect.signature(func)
    params = list(spec.parameters.values())
    if len(params) < 1:
        return False

    # First param must be positional or positional-or-keyword
    first = params[0]
    if first.kind not in (first.POSITIONAL_ONLY, first.POSITIONAL_OR_KEYWORD):
        return False

    # Rest must be keyword-only with defaults
    for p in params[1:]:
        if p.kind not in (p.KEYWORD_ONLY,):
            return False
        # Keyword-only args must have defaults to be optional
        if p.default is inspect.Parameter.empty:
            return False

    return True


